       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-whale-widget','DeepSeek-Balance-Whale-Widget','MeteorNOX','https://github.com/MeteorNOX/DeepSeek-Balance-Whale-Widget',NULL,'fun','DeepSeek Harness（DSH）一只住在 DSH 界面右下角的小鲸鱼娘，帮你盯着DeepSeek账户余额。QQ弹弹，支持拖拽吸附、左吸附翻转、数字滚动动画，随界面自动启用，建议直接喊来你的dsh安装','右下角常驻的小鲸鱼挂件：余额、今日已用与每轮对话消耗（含峰谷价），余额预警与今日预算的泡泡内容都可编辑；泡泡点击序列模块化自定义，支持并列加权 A/B、随机台词与随机图片；内置 30+ 厂商模板（OpenAI / OpenRouter / Kimi / 硅基流动 / 方舟 / 智谱 / MiniMax 等），按模型查余额与订阅额度；另有任务结束音效、导入音频、自定义角色与资源管理。数据全在本机，无遥测。','dsh-whale-widget',NULL,'dsh plugin add github:MeteorNOX/DeepSeek-Balance-Whale-Widget','github',4771,0,4771000,'0.4.2','2026-10-11','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'6f90e280')
