       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:clearai-dsh','clearai-dsh','Clearailhc','https://github.com/Clearailhc/clearai-dsh',NULL,'session','An agent preset for evidence-checked research: every step advances only through system-verified observations, L3+ claims go to an independent evaluator, and the session folds into a replayable ledger that grows into a browsable domain ontology. Requires DSH >=0.1.7-alpha.1.','以证据为准的研究用智能体预设：每一步只能靠系统核验过的观测推进，L3 以上的结论交给独立评估者，整场会话折成一份可重放的账本，并长成可浏览的领域本体。需要 DSH >=0.1.7-alpha.1。','clearai-dsh',NULL,'dsh plugin --profile web add clearai-dsh','npm',1281,0,1281000,'0.5.4','2026-10-03','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'2459af88')
