       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-deja','deja-vu','vshulcz','https://github.com/vshulcz/deja-vu',NULL,'memory','Coding agent memory for Claude Code, Codex, Cursor and 38 more, built from the session history already on your disk. Local search, MCP and hooks, no LLM, one Go binary.','读取本机上其他三十三个编程智能体已经写下的会话文件——Claude Code、Codex、Cursor、VS Code Copilot Chat、opencode、OpenClaw、Hermes、Kimi、Cline、Zed 等，包括安装之前的历史：提供 deja_recall、deja_session、deja_blame、deja_fix、deja_how、deja_remember 六个工具与 /deja 命令，并可选地把召回结果加入运行时上下文。本地 BM25 索引，不用大模型，不用向量嵌入，不联网（dsh plugin --profile web add dsh-deja）。','dsh-deja',NULL,'dsh plugin add github:vshulcz/deja-vu','github',1196,0,1196000,'0.22.1','2026-10-14','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'e9b6c4b8')
