       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@modusensus/dsh-mneme','mneme#dsh-mneme','slow-stack','https://github.com/slow-stack/mneme/tree/main/dsh-mneme',NULL,'memory','The memory that dreams — cross-session memory for DeepSeek Harness: recalls you across sessions, auto-consolidates in its sleep (autoDream), freezes conflicting memories for your review, and keeps a replayable audit trail. Offline-first local semantic search over SQLite with human-editable Markdown mirrors, an entity graph, an interactive memory panel, plus an external API and CLI.','会做梦的记忆 — DeepSeek Harness 跨会话记忆插件：跨会话记住你与项目、深夜 autoDream 自动巩固记忆、冲突记忆先冻结待你裁决、全程可回放审计。默认离线：SQLite 配人工可编辑的 Markdown 镜像，提供本地语义检索、实体图谱、交互式记忆库面板及外部 API 与 CLI。','@modusensus/dsh-mneme',NULL,'dsh plugin --profile web add @modusensus/dsh-mneme','npm',148,11118,159118,'0.8.16','2026-08-14','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'83b12e9c')
