       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:westfox-awa/dsh-prompt-optimizer','dsh-prompt-optimizer','WestFox-AwA','https://github.com/WestFox-AwA/dsh-prompt-optimizer',NULL,'memory','DSH 插件 · 注入式优化器 0.8（主线）：你照常说话，它在你发送后,AI接收前把"这一轮到底要什么"理清楚，再把这份理解交给工作 AI(上下文注入) —— 原话不改写，条条带逐字依据。含控制界面（档位/权限/模型/上下文/只读工具）、拦截浮层（思维层+产出层）与真实 token 用量。可明显提升大多数模型的发挥稳定性,尤其DeepSeek-V4.1-Flash,可有明显提升','发消息前先理清你这轮到底要什么，原话不动，把理解交给 AI，还能看真实 token 用量。',NULL,NULL,'dsh plugin add github:WestFox-AwA/dsh-prompt-optimizer','github',115,0,115000,'','2026-10-11','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'4d8b050a')
