       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-approval-gate','dsh-approval-gate','moon09300731','https://github.com/moon09300731/dsh-approval-gate',NULL,'security','DeepSeek Harness 自动审批门控：Flash 预判不可回补操作，安全自动批准、危险转人工（fail-safe）','dsh-approval-gate 的维护中 fork。判定器不可用时，确认次数已达阈值的中立操作直接自动放行，不再重复弹人工审批；审批说明由真实的沙箱模式、命令与路径生成中文。另含凭据外泄与系统路径销毁的确定性硬拒、判定输入脱敏、判定模型候选链、带操作指纹的放行规则，以及可查看 unified diff 与一键撤销的审批视图。','dsh-approval-gate',NULL,'dsh plugin add github:moon09300731/dsh-approval-gate','github',93,0,93000,'0.5.0','2026-08-20','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'932af24')
