       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-plugin-writing-guard','dsh-plugin-writing-guard','xmutfyh','https://github.com/xmutfyh/dsh-plugin-writing-guard',NULL,'tools','Academic writing guard (EN/ZH bilingual): removes AI-style defensive writing, protects scientific evidence (numbers, citations, claim strength, null findings, scope) during polishing, and calibrates writing toward a target journal (Journal Profile + Journal Fit). Deterministic local regex/statistics, zero network/LLM; writing_rules / writing_audit / writing_style_profile / writing_journal_profile with auto-audit on paper writes.','论文写作守卫（中英双语）：去掉 AI 式防御性写作，润色时守住科学证据（数字/引用/主张强度/零结果/scope），并按目标期刊校准写作风格（Journal Profile + Journal Fit）。纯本地正则/统计，零网络零 LLM；提供 writing_rules / writing_audit / writing_style_profile / writing_journal_profile，论文写入后自动审计。','dsh-plugin-writing-guard',NULL,'dsh plugin --profile web add dsh-plugin-writing-guard','npm',46,3667,49667,'2.0.1','2026-08-15','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'da6962ec')
