       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:andersen216/dsh-whale-girl-live2d','dsh-whale-girl-live2d','Andersen216','https://github.com/Andersen216/dsh-whale-girl-live2d#-安装--install',NULL,'fun','🐋 鲸鱼娘桌宠 · Whale Girl Live2D —— DSH（DeepSeek Harness）Web 界面里的 Live2D 桌宠：跟着 agent 的真实状态换表情与动作，点一下就能直接跟 agent 说话，右键是钱包。A Live2D desktop pet for the DSH Web UI. 安装 Install: dsh plugin --profile web add github:Andersen216/dsh-whale-girl-live2d','DSH 里的 Live2D 桌宠「鲸鱼娘」：模型常驻 Web 界面，跟着 agent 的真实状态换表情与动作（思考、调工具、逐字输出、报错、收工庆祝），点一下就能直接给 agent 发消息、回复逐字冒进气泡；右键菜单可换表情、戴眼镜贴纸、摆桌面场景、演一次性小动作，动作全部照模型作者自己的按键表设计，互不冲突、到点自动收回。模型素材非商业（CC BY-NC-SA 4.0），代码 MIT，作者 Andersen216。',NULL,NULL,'dsh plugin add github:Andersen216/dsh-whale-girl-live2d','github',35,0,35000,'','2026-10-11','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'d070eb11')
