       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@wingsky-1/dsh-lan-proxy','dsh-plugin-hub#packages/dsh-lan-proxy','wingsky-1','https://github.com/wingsky-1/dsh-plugin-hub/tree/main/packages/dsh-lan-proxy',NULL,'notify','Access the dsh web UI over LAN: HTTP/HTTPS/WS forwarding plus TLS (self-signed or custom certificates); adaptive Brotli/gzip compression for HTTP and permessage-deflate for WebSocket; half-open WebSocket probing keeps mobile clients from going stale after backgrounding; launch-token auto-injection lets LAN devices connect without copying the token; DNS-rebinding protection + loopback-only upstream allowlist.','局域网访问 dsh web UI：HTTP/HTTPS/WS 转发 + TLS（自签名/自定义证书）；HTTP 自适应 Brotli/gzip 与 WebSocket permessage-deflate 双压缩；WS 半开探活，移动端切后台不僵死；启动令牌自动注入，LAN 设备免手工拿 token；DNS 重绑定防护 + 回环-only 上游白名单。','@wingsky-1/dsh-lan-proxy',NULL,'dsh plugin --profile web add @wingsky-1/dsh-lan-proxy','npm',24,2487,26487,'0.2.9','2026-08-18','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'478463f3')
