INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-prime-memory','dsh-prime-memory','drscrewdriver','https://github.com/drscrewdriver/dsh-prime-memory',NULL,'memory','Layered memory for DSH whose agent-facing surface is 10 tools: high-privilege writes (memory_add, memory_delete, memory_import), rumination controls (memory_ruminate, _cancel, _status), and a memory graph (memory_search_graph, memory_expand_graph_node), built over an L0-L3 distillation pipeline that recalls and injects relevant memories before each model step.','分层记忆插件，面向 Agent 暴露 10 个工具：高权限写入（memory_add / memory_delete / memory_import）、反刍控制（memory_ruminate / _cancel / _status）与记忆图谱（memory_search_graph / memory_expand_graph_node），底层为 L0–L3 蒸馏管线，并在每步模型调用前召回注入相关记忆。','dsh-prime-memory',NULL,'dsh plugin --profile web add dsh-prime-memory','npm',4,15331,19331,'0.24.0','2026-09-18','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'5c9f67a4')
