       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-agnes-studio','dsh-agnes-studio','zmm863-commits','https://github.com/zmm863-commits/dsh-agnes-studio',NULL,'vision','AI image and video studio as a floating DSH panel, so creation runs alongside the conversation instead of replacing it: text-to-image, image-to-image and multi-image composition at 1K-4K across eight aspect ratios; text-to-video and image-to-video with first-frame control at 4-12 seconds; short-drama mode that imports a script (.txt/.md/.json), breaks it into storyboard shots for preview and batch generation; and a prompt-expert workspace. Zero runtime dependencies.','一站式 AI 影视创作工作站，作为 DSH 全局浮层面板运行，不占用对话框：生图（文生图 / 图生图 / 多图合成，1K–4K、8 种宽高比）、生视频（文生视频 / 图生视频，4–12 秒、支持首帧控制）、短剧（导入 .txt/.md/.json 剧本自动拆解分镜，故事板预览与批量生成）与提示词专家工作区。零运行时依赖。','dsh-agnes-studio',NULL,'dsh plugin --profile web add dsh-agnes-studio','npm',16,2153,18153,'0.7.1','2026-09-16','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'77b02473')
