       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:1420079678-ctrl/agent-body','agent-body#dsh-zero-residence','1420079678-ctrl','https://github.com/1420079678-ctrl/agent-body/tree/main/workspace/plugins/dsh-zero-residence',NULL,'session','Zero-residence context engine: large tool payloads are evicted out of the live context into a queryable store and only deterministic pointers are left behind, so per-turn prompt tokens stop growing with the transcript. Any masked content is reconstructed verbatim from the session log on demand, by tool-call id or session seq.','零驻留上下文引擎：把体积大的工具输出从活跃上下文驱逐到可查询存储，只留下确定性指针，于是每轮的提示词 token 不再随对话长度增长。被遮蔽的内容可随时从会话日志逐字重建，按工具调用 id 或会话 seq 定位。',NULL,'https://github.com/1420079678-ctrl/agent-body/releases/download/v0.1.1/dsh-external-dsh-zero-residence-0.1.0.tgz','dsh plugin --profile web add "https://github.com/1420079678-ctrl/agent-body/releases/download/v0.1.1/dsh-external-dsh-zero-residence-0.1.0.tgz"','tarball',17,0,17000,'','2026-09-27','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'26f701ef')
