       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-solution-explorer','dsh-solution-explorer','xiaoksio','https://github.com/xiaoksio/dsh-solution-explorer',NULL,'dev','DSH Web GUI right sidebar: VS Code-style file explorer plus source control (git status, stage/unstage/discard, commit, diff, commit graph, fetch/pull/push sync, branch and remote management, git init, multi-repo switch, color-coded file status, file-type icons), an editor view that opens every file reached from the chat, the file tree or source control (Markdown/HTML/PDF/image previews, 15-language syntax highlighting, hunk-level diff editing, Ctrl+S save), file operations (new/move/copy/delete, reveal in file explorer), a collapsible icon rail, a multi-tab bottom terminal (ConPTY), and commit messages generated from the staged diff by a host-configured model.','DSH Web GUI 右侧边栏：VS Code 风格文件浏览器加源代码管理（git 状态、暂存/取消暂存/放弃变更、提交、差异、提交图形、抓取/拉取/推送同步、分支与远程管理、Git 初始化、多仓库切换、文件状态着色、文件类型图标），并提供打开会话/文件树/源代码管理里任一文件的编辑器视图（Markdown/HTML/PDF/图片预览、15 种语言语法高亮、逐块差异编辑、Ctrl+S 保存）、文件操作（新建/移动/复制/删除、在文件管理器中显示）、可折叠图标窄条、多标签底部终端（ConPTY），以及由宿主已配置模型基于暂存差异生成提交信息。','dsh-solution-explorer',NULL,'dsh plugin --profile web add dsh-solution-explorer','npm',11,1678,12678,'1.0.2','2026-08-24','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'3c808cb0')
