INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:yangshen-swe/dsh-plugin-simple-pet','dsh-plugin-simple-pet','YangShen-SWE','https://github.com/YangShen-SWE/dsh-plugin-simple-pet',NULL,'session','A Windows desktop pet with optional quiet mode, classic/gentle feedback and independent reduced-motion/flash/floating-text controls, preserving classic defaults and updating real data without replaying old events. Includes five independent cardTheme palettes (default/original blue, forest/green, amber/brown, violet/purple-gray and paper/white) freely paired with six 2D character skins; each palette supports DeepSeek wallet, peak/off-peak pricing and cache information, or Codex 5-hour/weekly quotas and reset times. The host-native DSH settings gallery shows both modes and character/card combinations with clearly labeled synthetic preview values; explicit saves hot-reload without new model requests or account changes. v0.6.5 separates disk saves and drafts from a recent successful native application receipt, verified against the owned process/run/profile, raw revision, effective preferences and a short lease; stale or failed evidence never claims success. Retains draggable positioning, inert right-click, four sizes, preferences/statistics, responsive light/dark settings, authenticated atomic saves, configurable quota polling and default-off deduplicated warm-up.','Windows 桌宠支持可选安静模式、经典／温和反馈，以及减少动态、关闭闪光和飘字的独立舒适选项；默认保留经典，真实数据持续更新，退出静态状态不补播旧事件。信息框 cardTheme 可与六款 2D 人物 skin 任意搭配，提供海盐蓝（default，保留原色）、苔庭墨绿（forest）、焦糖暖棕（amber）、暮云紫灰（violet）、月笺雾白（paper）五版；每版均支持 DeepSeek 钱包、峰谷价牌与缓存信息，以及 Codex 5 小时／周额度与重置时间双模式。DSH 原生设置中的主题图库同时展示双模式及人物／信息框小组合预览，明确标注合成示例数字，点击保存后热更新，不新增模型请求或账号变更。v0.6.5 将写盘成功、草稿与桌宠近期实际应用回执分开，通过自己启动的进程／启动／profile、原始修订、实际偏好和短租约核验，过期或失败不误报成功。保留拖动与独立坐标、右键无菜单或弹窗、四档尺寸、偏好／统计、深浅主题与窄屏适配、鉴权原子保存、可配置额度检测，以及默认关闭、持久去重的独立预热。',NULL,'https://github.com/YangShen-SWE/dsh-plugin-simple-pet/releases/latest/download/dsh-plugin-simple-pet.tgz','dsh plugin --profile web add github:YangShen-SWE/dsh-plugin-simple-pet','github',12,0,12000,'','2026-10-07','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'2959e501')
     ON CONFLICT(id) DO UPDATE SET stars=excluded.stars, downloads=excluded.downloads, score=excluded.score,
