       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:heartmove/dsh-side-chat','dsh-side-chat','heartmove','https://github.com/heartmove/dsh-side-chat',NULL,'security','一个 DSH 网页插件，Codex 式侧边聊天的强化版本： 在右侧面板提供按主会话隔离的独立聊天，具备 Codex 式的智能体能力——继承主会话的 工具集、模型、思考难度与权限预设，能感知所在工作目录；选中对话内容即可提问，AI 回复 也能带回主会话（直接带回或摘要后带回，写入草稿或注入为折叠提示行）。  在 Codex 式能力之上，它额外支持：当主会话的智能体弹出问题弹框向你提问时，可以 把问题与各个选项带入侧边聊天、让 AI 帮你分析，不必打断当前流程——想清楚后把答案 带回，再回答弹框即可。','在对话中选中内容，即可在右侧边栏开启独立聊天，针对选中部分提问，不打断主对话。',NULL,NULL,'dsh plugin add github:heartmove/dsh-side-chat','github',12,0,12000,'','2026-09-24','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'2f895cbf')
