INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@mtl-academic/dsh-patent','Aurify#bundle-patent','ai-tools-mtl','https://github.com/ai-tools-mtl/Aurify/tree/main/packages/bundle-patent',NULL,'tools','Patent-writing gatekeeper for dsh - screens the idea against Chinese prior art first, then runs five-party alignment interviews, eight-chapter disclosure drafting, figures and simulation runs, seven-dimension review and docx/PDF export. Skills work out of the box; the search, export and experiment tools come from a bundled Python MCP service that ships disabled - one line in ~/.dsh/patent-services.yaml enables it, and uvx fetches the wheel from PyPI.','dsh 专利撰写把关人：动笔前先检索中国专利给出三档结论，再走五方对齐访谈、八章交底书、附图与仿真实验、七维审查与 docx/PDF 导出全流程。技能开箱即用；检索、导出与实验工具来自内置的 Python MCP 服务，默认关闭——在 ~/.dsh/patent-services.yaml 里开一行即启用，uvx 会从 PyPI 自动拉取。','@mtl-academic/dsh-patent',NULL,'dsh plugin --profile web add @mtl-academic/dsh-patent','npm',9,1985,10985,'0.1.6-alpha.7','2026-09-24','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'b5454e3f')
