       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-memory-palace','dsh-memory-palace','lovezi0','https://github.com/lovezi0/dsh-memory-palace',NULL,'memory','Human-readable Markdown memory for DeepSeek Harness: user-level (~/.deepseek-harness/MEMORY.md) + workspace-level memory injected every turn, auto daily-log writing with distillation, bridges existing WorkBuddy/CodeBuddy memory dirs, memory_note / memory_note_user / memory_read tools with built-in dedup, and a bilingual settings page. Plain-text storage, no database.','人类可读的 Markdown 记忆插件：用户级（~/.deepseek-harness/MEMORY.md）+ 工作区级双层记忆，每轮自动注入提示词，回合结束自动写日志并按期蒸馏沉淀；可桥接已有 WorkBuddy/CodeBuddy 记忆目录；内置 memory_note / memory_note_user / memory_read 三个工具（自动去重）与中英双语设置页。纯文件存储、无数据库，记事本即可编辑。','dsh-memory-palace',NULL,'dsh plugin --profile web add dsh-memory-palace','npm',6,3987,9987,'1.8.0','2026-08-16','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'afbf31ad')
