       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@zzerx/dsh-plugin-memory','dsh-forge-studio#plugin-memory','0x7A7A6572','https://github.com/0x7A7A6572/dsh-forge-studio/tree/main/packages/plugin-memory',NULL,'memory','Cross-session memory for DeepSeek Harness: agents save, search and update user preferences, facts and project decisions; important entries are injected into later sessions, and a Settings section lists, edits, archives or deletes them.','dsh 跨会话记忆：agent 保存、检索并更新用户偏好、事实与项目决策，重要条目自动注入后续会话，设置面板可浏览、编辑、归档与删除。','@zzerx/dsh-plugin-memory',NULL,'dsh plugin --profile web add @zzerx/dsh-plugin-memory','npm',6,2434,8434,'0.4.3','2026-09-18','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'5aa0cc99')
