INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-version-update','dsh-version-update','SuCriss','https://github.com/SuCriss/dsh-version-update',NULL,'dev','Version management for dsh: inspect the installed version against every npm channel or version line, install or downgrade in one click, stream the install log live (rollback-snapshot copy progress, npm extraction progress, elapsed time), roll back instantly from local snapshots, and automate the cycle with a policy engine (silent auto-update, execution windows, daily checks). Never stops npm mid-install — a wedged run is only stopped after an hour, and a half-committed global tree is detected and repaired from the pre-install snapshot automatically. Confirms before installing a found update, auto-restarts the host after install, and falls back to a mirror when the primary registry is unreachable.','DeepSeek Harness 版本管理：对照各 npm 通道或版本线查看已装版本，一键安装或降级，安装日志实时流出（回滚快照复制进度、npm 提取进度、已运行时长），从本地快照秒级回滚，用策略引擎（静默自动更新、执行时间窗、每日检查）托管整个流程。绝不在安装中途终止 npm——卡死的任务要等一小时才会停止，半提交的全局安装树会被自动检测并从安装前快照修复。检查到新版本时弹窗确认是否立即更新，安装后自动重启宿主，遇到 registry 不可达时自动回退到镜像。','dsh-version-update',NULL,'dsh plugin --profile web add dsh-version-update','npm',5,2589,7589,'1.4.4','2026-08-22','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'45a0f620')
     ON CONFLICT(id) DO UPDATE SET stars=excluded.stars, downloads=excluded.downloads, score=excluded.score,
       install_target=excluded.install_target, target_kind=excluded.target_kind, version=excluded.version,
