       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:haoranwang0921/dsh-session-cleaner','dsh-session-cleaner','haoranwang0921','https://github.com/haoranwang0921/dsh-session-cleaner',NULL,'session','Manage conversation records from the DSH web GUI settings page: delete a whole session (archive plus physical log removal) or a single message (deleting a user message cascades to its assistant replies and tool results). Running and current sessions are protected.','在 DSH Web GUI 设置页管理对话记录：可删除整个会话（归档并物理删除日志），或按用户消息分组浏览并删除单条消息（删除用户消息会级联删除其引发的助手与工具消息）。运行中与当前会话受保护。',NULL,NULL,'dsh plugin --profile web add github:haoranwang0921/dsh-session-cleaner','github',7,0,7000,'','2026-08-23','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'b73b3e5f')
