       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-session-fork','dsh-session-fork','Jason-skd','https://github.com/Jason-skd/dsh-session-fork',NULL,'session','Git-style conversation branching that mirrors how real programmers collaborate: a secretary root branch dispatches tasks to child branches with their own contexts, merging back only compressed summaries via squash or rebase; ships /branch commands, a branch tab, branch-to-branch messaging, and a governance baseline pairing each session branch with a git worktree.','Git 式会话分支，模拟真实程序员协作的并行开发：根分支充当秘书维持调度，子分支持有各自上下文并行工作，任务完成后仅以压缩摘要 squash/rebase 合并回来；提供 /branch 命令、分支页签、send_message_by_branch 跨分支消息，并附一份把会话分支绑定到 git worktree 的治理基线。','dsh-session-fork',NULL,'dsh plugin --profile web add github:Jason-skd/dsh-session-fork','github',7,0,7000,'','2026-08-23','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'d98123e9')
