       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@creait/dsh-hookkit','dsh-plugins#hookkit','CREAIT-nl','https://github.com/CREAIT-nl/dsh-plugins/tree/main/hookkit',NULL,'agent','Config-driven lifecycle hooks, including context injection: declare event, handler and outcome in YAML, where the handler is an in-harness tool (MCP included), a shell command or an HTTP endpoint, and the outcome is model-visible context, a denied tool call, or fire-and-forget.','以配置驱动的生命周期钩子，并支持上下文注入：在 YAML 中声明事件、处理器与结果——处理器可以是进程内工具（含 MCP）、shell 命令或 HTTP 端点，结果可以是模型可见的上下文、拒绝该次工具调用，或触发即忘。','@creait/dsh-hookkit',NULL,'dsh plugin --profile web add @creait/dsh-hookkit','npm',6,730,6730,'0.1.0','2026-08-24','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'ff0e67d8')
