       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@creait/dsh-web-fetch','dsh-plugins#web-fetch','CREAIT-nl','https://github.com/CREAIT-nl/dsh-plugins/tree/main/web-fetch',NULL,'browser','A guarded local fetch provider for the ctx.web seam — the backend dsh does not ship for its own web_fetch tool. Every redirect hop is re-resolved and checked against the non-routable ranges, with a streamed size cap and a content-type allowlist.','ctx.web 接口的本地受控抓取提供方——dsh 自带完整的 web_fetch 工具，却没有随附后端。每一跳重定向都会重新解析并对照非公网地址段校验，另有流式大小上限与内容类型白名单。','@creait/dsh-web-fetch',NULL,'dsh plugin --profile web add @creait/dsh-web-fetch','npm',6,719,6719,'0.1.0','2026-08-24','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'15c5337d')
