       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-quick-toc','dsh-quick-toc','LyaxZ','https://github.com/LyaxZ/dsh-quick-toc',NULL,'ui','Conversation outline for DeepSeek Harness: whole-session Markdown headings grouped by turn, in a side panel or a full-width curtain; hover previews that pin for side-by-side comparison; title, prompt, full-text and cross-session search with the recent queries kept; multiple jump actions, reading-position follow, adjustable outline density, and a Chinese/English interface; settings one click from the panel toolbar.','DeepSeek Harness 对话大纲：按回合整理整段会话的 Markdown 标题，侧边面板与全屏幕布两种视图；悬停预览可钉住对照；标题、提问、全文与跨会话四档检索，并保留最近搜索过的词；多种跳转、阅读位置跟随、可调大纲密度与中英双语界面；设置卡片从顶栏按钮直达。','dsh-quick-toc','https://github.com/LyaxZ/dsh-quick-toc/releases/latest/download/dsh-quick-toc.tgz','dsh plugin --profile web add dsh-quick-toc','npm',1,5719,6719,'0.9.4','2026-08-18','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'47825c34')
