       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@signalight/dsh-codex-pet','codex-to-dsh-pet#dsh-codex-pet','Signalight','https://github.com/Signalight/codex-to-dsh-pet/tree/main/packages/dsh-codex-pet',NULL,'fun','DSH web-GUI pet runtime that renders any Codex spritesheet-atlas pet (v1/v2) as a draggable overlay: drag/wave/jump, v2 mouse-tracking eyes that follow the active mouse, live agent-status poses, progress bubbles, and an in-GUI atlas importer; ships one original CC BY-NC demo pet (nastya), and user pets live in ~/.dsh/pets.','DSH 网页 GUI 实时桌宠：可把任何 Codex 桌宠图集（webp/png/gif，v1/v2 自动识别）转换为 DSH 中可拖拽的悬浮桌宠。支持拖拽/挥手/跳跃，v2 桌宠的眼睛实时追踪活动鼠标，随 agent 状态切换姿势；进度气泡反映工作状态；「设置 → 桌宠」图形界面可导入、切换与调整桌宠；内置一只原创示例桌宠（娜斯佳），用户桌宠存放在 ~/.dsh/pets。','@signalight/dsh-codex-pet',NULL,'dsh plugin --profile web add @signalight/dsh-codex-pet','npm',5,1605,6605,'0.4.1','2026-08-18','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'c95b124d')
