INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@zmainer/dsh-wx-bridge','dsh-wx-bridge','zhy5','https://github.com/zhy5/dsh-wx-bridge',NULL,'notify','Drive your local DSH from WeChat: a self-hosted iLink bridge over a persistent ACP session (context lives in DSH and is resumable), phone conversations grouped into the desktop workspace, with image recognition, file messages (Excel/Word/PDF, parsed by the agent itself) and voice transcripts. Tool approvals are answered inside WeChat itself (numbered card; ask/allow/reject policy; 120s timeout means reject), and any process can push a message to your phone through the outbox helper. Access defaults to strict (only registered devices are served); the phone channel''s permission preset is configurable - see the README security section before sharing the bot.','手机微信驱动本机 DSH：自建 iLink 桥 + 常驻 ACP 原生会话（上下文归 DSH、可 resume），手机会话自动登记进桌面工作区；支持图片识别、直接发文件（Excel/Word/PDF，由会话里的 agent 自行解析）与语音转写。审批可在微信里应答（编号卡片，ask/allow/reject 策略，超时按拒绝），任何进程也能通过 outbox 推送把消息发到手机。准入默认 strict（只服务已登记设备）；手机通道权限预设可配置，详见 README 安全基线。','@zmainer/dsh-wx-bridge',NULL,'dsh plugin --profile web add @zmainer/dsh-wx-bridge','npm',1,4191,5191,'1.1.8','2026-09-24','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'fbede181')
     ON CONFLICT(id) DO UPDATE SET stars=excluded.stars, downloads=excluded.downloads, score=excluded.score,
