INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@duke-dsh-plugins/dsh-model-prompt-injector','dsh-model-prompt-injector','MoonlitDropOfBlood','https://github.com/MoonlitDropOfBlood/dsh-model-prompt-injector',NULL,'model','Per-model system prompt injector for DeepSeek Harness: append custom prompt text to the END of the system prompt for locally configured models, matched by exact provider/model route or a provider-wide provider/* rule (both stack in order). A Settings page lists every configured provider and its models for per-route editing with instant effect, and rules persist to DSH_HOME so they survive restarts. Applies to main sessions, subagents, and workflow children alike.','DSH 按模型注入系统提示词：为本地已配置的模型把自定义提示词追加到系统提示词末尾，支持 provider/model 精确匹配与 provider/* 服务商级通配（两者按序叠加）。设置页自动列出每个已配置服务商及其模型，逐行编辑、即时生效；规则持久化保存、重启不丢；对主会话、subagent 与 workflow 子代理同样生效。','@duke-dsh-plugins/dsh-model-prompt-injector',NULL,'dsh plugin --profile web add @duke-dsh-plugins/dsh-model-prompt-injector','npm',3,1831,4831,'1.2.0','2026-09-07','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'4c1ffac9')
