       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-autotier','dsh-autotier','PerryLink','https://github.com/PerryLink/dsh-autotier',NULL,'model','Automatic model-tier routing for DeepSeek Harness: one user instruction enters, one tier decision comes out — complex intent is planned on the strong tier and implemented on the cheap tier, simple intent stays cheap throughout, with a deterministic guard and a TTL escalation fallback.','自动模型档位路由：一条用户指令进入、一个档位决策出来——复杂意图由强档规划、廉价档执行，简单意图全程廉价档，确定性护栏 + TTL 升级回退。','dsh-autotier',NULL,'dsh plugin --profile web add dsh-autotier','npm',1,3829,4829,'0.2.16','2026-09-13','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'4578dbd7')
