       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-git-forge','dsh-git-forge','OMSociety','https://github.com/OMSociety/dsh-git-forge',NULL,'dev','Project-scoped Git credentials for DeepSeek Harness: forge accounts (GitHub, Gitea, GitLab, Bitbucket or a custom host) live in the right-sidebar "Git Forge" tab, are granted per project, and reach the agent as an HTTPS credential helper so the token never enters the conversation. Pushes to a host the project has not granted are rejected.','为 DeepSeek Harness 提供项目级 Git 凭据：forge 账号（GitHub、Gitea、GitLab、Bitbucket 或自定义域名）在右侧栏「Git 凭据」标签页里管理并可按项目授权，再由生成的凭据 helper 交给 agent 走 HTTPS 推送，token 不进对话；未授权 host 的推送会被拦截器直接拒绝。','dsh-git-forge',NULL,'dsh plugin --profile web add dsh-git-forge','npm',4,800,4800,'1.2.0','2026-10-10','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'882d5859')
