INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-living-memory','dsh-living-memory','dearbld','https://github.com/dearbld/dsh-living-memory',NULL,'memory','Self-tending living memory in one local SQLite file — a nightly patrol dedupes, merges, decays and cross-links entries on its own, with seven-signal RRF hybrid recall (FTS5 + jieba Chinese-first tokenization, optional vector KNN, graph PPR), a typed knowledge graph, conflict detection instead of silent overwrites, and web telemetry panels.','单文件本地 SQLite 的自整理活记忆——夜巡引擎自动去重、合并、衰减、建链，七信号 RRF 混合检索（FTS5+jieba 中文优先分词、可选向量 KNN、图谱 PPR），带类型知识图谱，冲突检测标记矛盾而非静默覆写，Web 遥测面板。','dsh-living-memory',NULL,'dsh plugin --profile web add dsh-living-memory','npm',2,2437,4437,'0.2.10','2026-09-06','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'bf50ccf5')
