       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-knj-workflow','dsh-knj-workflow','yangdongzhen590','https://github.com/yangdongzhen590/dsh-knj-workflow',NULL,'agent','Config-driven development-task orchestration for DSH: graph workflows (task/gateway/human nodes) with per-stage persistence, plus an in-editor AI assistant that configures workflows through conversation with live validation. Hand documents to nodes as generic attachments (no declaration needed): files land in the task workspace and ${inputs.附件} gives the newline-joined absolute paths, so a node parses them with its own prompt.','配置驱动的工作流与开发任务编排：图式工作流（任务/网关/人工审批节点）+ 阶段级断点持久化，内置 AI 助手在图编辑器中通过对话配置工作流，逐条校验实时应用到画布。把文档作为「通用附件」交给节点（无需声明）：文件启动前落到工作区，节点用 ${inputs.附件} 拿到换行拼接的绝对路径自行解析。','dsh-knj-workflow',NULL,'dsh plugin --profile web add dsh-knj-workflow','npm',3,1205,4205,'2026.9.192','2026-08-27','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'6a96d6f9')
