       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-recall','dsh-recall','Relistencode','https://github.com/Relistencode/dsh-recall',NULL,'memory','Conversation history recall for DSH: three-layer (literal/fuzzy/semantic) retrieval over every past session''s original text, fully local & offline — AI never forgets what you told it. One-command install via `dsh.bundle.patch`, semantic layer runs in a worker thread.','对话历史回忆：字面/模糊/语义三层检索全部历史会话的原始文本，完全本地离线——AI 再也不会忘记你说的话。一条命令安装（自带 `dsh.bundle.patch`），语义推理跑在 worker 线程。','dsh-recall',NULL,'dsh plugin --profile web add dsh-recall','npm',3,1203,4203,'0.3.0','2026-08-16','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'a329877b')
