       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-undo-plugin','dsh-undo-plugin','23swccp','https://github.com/23swccp/dsh-undo/tree/master/packages/bundle-rollback',NULL,'session','Conversation and workspace undo: use the /undo timeline, session-header action, or message icon to roll back before any sent prompt; private Shadow Git snapshots restore files, the reverted turns stay out of model context, and Undo Rollback can recover mistakes. Includes archived-session management and per-tool colored cards.','对话与工作区撤销：通过 /undo 节点轴、会话头部按钮或消息下方图标回滚到任意已发送 prompt 之前；插件私有 Shadow Git 快照恢复文件，被回滚回合不会进入模型上下文，误操作还能“撤回回滚”。附带归档会话管理与工具卡片分类配色。','dsh-undo-plugin',NULL,'dsh plugin --profile web add dsh-undo-plugin','npm',3,998,3998,'0.1.0-rc.8','2026-08-21','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'2f58614a')
