INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-word-vault','dsh-word-vault','wangzhanchao883','https://github.com/wangzhanchao883/dsh-word-vault',NULL,'tools','English word bank for one or more children: words marked on textbook or workbook photos (highlighter, red pen) are found by their marks, then translated and stored in a local SQLite bank with an occurrence count; the clipboard picker, the photo route and dictation all land in the same bank. High-frequency words surface by count, three correct answers in a row flag a word as learned, and any selection prints as a memory card set (a word split into chunks, real IPA per chunk, a mnemonic hook, an A4 sheet of eight) in HTML, PDF or Word, with a print-and-answer exam page whose four options are set against each other for meaning. Requires DSH 0.1.7 or newer (1.0.3 moved to the 0.1.7 settings contract); 1.0.4 is tested on 0.2.0-rc.1, so 0.1.7 through 0.2.x all work. On 0.1.5 the settings panel does not appear - install dsh-word-vault@1.0.2 instead.','一个或多个孩子的英语生词库：课本/作业照片上被荧光笔或红笔标出的词按标记找出来，翻译后进本机 SQLite，并累计出现次数；剪贴板点选、拍照、对话三种录入进的是同一本库。高频词按次数浮现，连对三次自动标记「已学会」；勾选任意若干词可出记忆卡（拆解块 + 每块真实 IPA 音标 + 荒诞梗，A4 每页 8 张），输出 HTML/PDF/Word，并可出一份四选项按词义互斥的打印试卷作答。 需要 DSH 0.1.7 及以上（1.0.3 起改用 0.1.7 的设置契约）；1.0.4 已在 0.2.0-rc.1 实测，0.1.7 ~ 0.2.x 均可使用。在 0.1.5 上设置面板不会出现，可改装 dsh-word-vault@1.0.2。','dsh-word-vault',NULL,'dsh plugin --profile web add dsh-word-vault','npm',1,2975,3975,'1.10.0','2026-09-18','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'4db7d100')
