       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-simulated-life','dsh-simulated-life','john-walks-slow','https://github.com/john-walks-slow/dsh-simulated-life',NULL,'memory','Simulated life context for DeepSeek Harness: every turn injects the past 24h of simulated life events from the workspace .life/ directory (sliding-window filter, session-level deduplication with delta updates, world summary) as a collapsed context notice, and the life_react tool lets the agent record feelings, thoughts and actions back into its life log for the next round of world evolution — turning a DSH agent into a roleplay character with a persistent daily life.','为 DeepSeek Harness 的 Agent 提供拟真生活上下文：每轮对话自动注入工作区 .life/ 目录近 24 小时的生活事件（滑动窗口过滤、会话内智能去重与增量更新、世界近况），并提供 life_react 工具让 Agent 把感受、思考与行动回填到自己的生活日志，反哺下一轮世界演化——把 DSH Agent 变成有日常生活的角色扮演人设（适合酒馆式 RP、AI 陪伴）；配合每日世界演算工作流可获得持续的模拟人生式生活轨迹。','dsh-simulated-life',NULL,'dsh plugin --profile web add dsh-simulated-life','npm',2,1737,3737,'0.1.2','2026-09-21','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'470351c4')
     ON CONFLICT(id) DO UPDATE SET stars=excluded.stars, downloads=excluded.downloads, score=excluded.score,
