INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@lp181818/dsh-vision-plugin','dsh-vision-plugin','bug-huntter','https://github.com/bug-huntter/dsh-vision-plugin',NULL,'vision','Configurable image recognition for text-only DSH models: image messages are first transcribed by an OpenAI-compatible vision model (Base URL, model ID and API key set in a Settings section) and then passed to the main model as text, while image-input support is advertised. The API key auth scheme is selectable — OpenAI, Anthropic, Gemini or Azure style request headers — and a missing key is reported before any request is sent.','为纯文本 DSH 模型增加可配置识图能力：开启后图片消息先由任意 OpenAI 兼容视觉模型转写为文字描述，再交给主模型处理；设置页可配置 Base URL、Model ID 与密钥，并可选择密钥的鉴权方式（OpenAI / Anthropic / Gemini / Azure 风格请求头）；未填写密钥时会在发起请求前明确提示。','@lp181818/dsh-vision-plugin',NULL,'dsh plugin --profile web add @lp181818/dsh-vision-plugin','npm',2,1737,3737,'1.2.3','2026-09-05','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'b7760a71')
