       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-model-visibility','dsh-model-visibility','Lzh3070','https://github.com/Lzh3070/dsh-model-visibility',NULL,'session','Model visibility manager for DeepSeek Harness: hide or show any model in the conversation model selector from a dedicated settings page. Per-model switches, search, provider-level batch actions, reset-all. Zero intrusion - writes only its own hidden list, never the provider config; hiding a model in use never interrupts a running session.','DSH 模型可见性管理：在独立的设置分区页里按渠道/模型隐藏或显示模型选择菜单中的条目。逐模型开关、实时搜索、渠道级批量隐藏/显示、一键恢复全部。零侵入——只写插件自己的隐藏列表，不改 Provider 配置，隐藏正在使用的模型不会中断会话。','dsh-model-visibility',NULL,'dsh plugin --profile web add dsh-model-visibility','npm',2,1648,3648,'0.2.1','2026-08-28','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'b890ea77')
