       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-message-datetime','dsh-message-datetime','john-walks-slow','https://github.com/john-walks-slow/dsh-message-datetime',NULL,'session','One-line clock context for DeepSeek Harness: a Current time timestamp reading (weekday, date, time, UTC offset, IANA timezone) opens every conversation turn and a Turn ended reading closes it, so the model always knows the time, date and idle gap across turns without asking.','每轮对话开始向模型上下文注入单行时间戳读数（星期 / 日期 / 时间 / UTC 偏移 / IANA 时区），收尾再注入 Turn ended 关闭读数——模型始终知道现在几点、今天星期几、上一轮何时结束，日期运算与跨轮间隔不再靠猜；轻量时钟感知，每条约 30 token。','dsh-message-datetime',NULL,'dsh plugin --profile web add dsh-message-datetime','npm',2,1609,3609,'0.1.2','2026-09-21','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'3ce3c6eb')
