       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@ryuu-64/dsh-find-all','dsh-find-all','Ryuu-64','https://github.com/Ryuu-64/dsh-find-all',NULL,'ui','Adds a Cmd/Ctrl+F find bar to the DSH desktop app, and it searches the whole conversation: when a match sits in history that is not on screen yet, the plugin pages that history in and searches again, so the match count and the highlights cover the entire session instead of only the rendered messages.','给 DSH 桌面 App 补上 Cmd/Ctrl+F 查找栏，搜的是整段会话：命中落在还没显示出来的历史里时，插件会把更早的消息分页加载进来再搜一遍，命中计数和高亮因此覆盖整段会话，而不只是屏幕上那一截。','@ryuu-64/dsh-find-all',NULL,'dsh plugin --profile web add @ryuu-64/dsh-find-all','npm',0,3443,3443,'0.1.12','2026-09-22','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'b22a086c')
