INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-disk-manager','dsh-disk-manager','wangzhanchao883','https://github.com/wangzhanchao883/dsh-disk-manager',NULL,'tools','Scans the whole C drive and classifies every large folder into A/B/C/D/E/P (safe cache / relocatable / junction-movable / abandoned software / config-memory redline / personal files), then deletes, moves, or redirects on demand — with strong redline protection, dry-run preview and undo. Unknown software decided by LLM fallback + human confirmation. Works on DeepSeek Harness 0.1.7 through 0.2.x, tested on 0.2.0-rc.1.','扫描整 C 盘,把每个大空间按 A/B/C/D/E/P 分类(无忧缓存/官方可改址/可junction搬/冷废弃软件/配置记忆红线/个人文件),再按需删缓存/junction搬走/引导改址,带强红线保护、dry-run 预览与 undo。未知软件由 LLM 兜底 + 人工确认,动手前先预览、做完可回滚。 支持 DSH 0.1.7 ~ 0.2.x,已在 0.2.0-rc.1 实测。','dsh-disk-manager',NULL,'dsh plugin --profile web add dsh-disk-manager','npm',1,1581,2581,'0.1.3','2026-09-06','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'c863c080')
