       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-agentnoodle','dsh-agentnoodle','bigharm','https://github.com/bigharm/dsh-agentnoodle',NULL,'fun','Extensible AI-driven group-reaction narrative game framework for DeepSeek Harness: type one action and multiple NPCs each respond in their own chatroom message with avatar illustrations; worlds, locations, NPCs and feature extensions (e.g. a third-party drawing API for dynamic NPC expressions) are added and modified through the harness chat dialog without code.','DeepSeek Harness 插件：可扩展的 AI 群像聊天游戏框架。输入一个行动，多个 NPC 各自回应，每条反应独立成带头像插图的聊天室消息；世界、地点、NPC 与功能扩展（如接入第三方绘图 API 实现 NPC 动态表情动作）都可以在对话框里让 agent 直接添加修改，无需写代码。','dsh-agentnoodle',NULL,'dsh plugin --profile web add dsh-agentnoodle','npm',1,1009,2009,'0.1.14','2026-08-31','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'d2c0906')
