       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:jimchen-g/dsh-action-outbox','dsh-action-outbox','JimChen-g','https://github.com/JimChen-g/dsh-action-outbox',NULL,'security','Stages exact DSH tool calls without dispatch, presents complete canonical arguments in a durable Batch Review Inbox, invalidates approvals after edits or restarts, and commits only a matching SHA-256 digest plus single-use nonce through the normal DSH tool pipeline.','暂存精确的 DSH 工具调用而不执行，在持久化批量审查收件箱中展示完整规范参数；编辑或重启后审批失效，仅允许携带匹配 SHA-256 摘要与一次性 nonce 的批次通过 DSH 正常工具管线提交。',NULL,'https://github.com/JimChen-g/dsh-action-outbox/releases/download/v0.3.0/dsh-action-outbox-0.3.0.tgz','dsh plugin --profile web add "https://github.com/JimChen-g/dsh-action-outbox/releases/download/v0.3.0/dsh-action-outbox-0.3.0.tgz"','tarball',2,0,2000,'','2026-09-20','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'1217a566')
