       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-connect-agnes-token-plan','dsh-connect-agnes-token-plan','eghrhegpe','https://github.com/eghrhegpe/dsh-connect-agnes-token-plan',NULL,'session','Agnes Token Plan quota panel rendered as a config card on the Harness Plugins page: account-wide quota windows (5-hour requests, weekly requests, daily images, daily video) plus cumulative usage with a daily chart and the public plan catalogue, all read from the Agnes console API, with in-panel sign-in and automatic re-login. Four opt-in switches, off by default, register the Agnes models as an LLM provider, connect the AgnesCode desktop-app login state as a second upstream provider, and expose image- and video-generation tools to the agent.','在 Harness 的 Plugins 页以插件卡显示 Agnes 控制台的 Token Plan 额度：账号级四类额度窗口（5 小时请求、每周请求、每日图片、每日视频）、账号累计用量与按日柱图、以及公开套餐目录，支持面板内登录与令牌失效后自动重登。另有四个默认关闭的可选开关：把 Agnes 模型注册为 DSH 推理提供方、接入 AgnesCode 桌面端上游，并向 agent 暴露图片与视频生成工具。','dsh-connect-agnes-token-plan',NULL,'dsh plugin --profile web add dsh-connect-agnes-token-plan','npm',0,1648,1648,'0.10.2','2026-10-13','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'11b8c7b2')
