INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-lost-and-found','dsh-lost-and-found','wangzhanchao883','https://github.com/wangzhanchao883/dsh-lost-and-found',NULL,'tools','Local file recall: indexes the folders you choose into one local SQLite database, so ''where did I put that file?'' is one query instead of a disk walk. Caches, VCS and program folders are pruned per directory; each folder keeps its own incremental anchor, so a folder added later is backfilled in full. Read-only: it never modifies, moves or deletes your files. Works on DeepSeek Harness 0.1.7 through 0.2.x, tested on 0.2.0-rc.1.','本地文件记忆索引：把指定的文件夹记进本机一个 SQLite 库，忘了东西放哪问一句就能找回，不必翻硬盘；缓存、版本库与程序目录整棵跳过。每个目录各有独立增量锚点，后加入的目录首扫回填全部历史。只读，绝不修改、移动或删除你的文件。 支持 DSH 0.1.7 ~ 0.2.x,已在 0.2.0-rc.1 实测。','dsh-lost-and-found',NULL,'dsh plugin --profile web add dsh-lost-and-found','npm',0,1483,1483,'0.1.5','2026-09-18','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'687ddf9e')
     ON CONFLICT(id) DO UPDATE SET stars=excluded.stars, downloads=excluded.downloads, score=excluded.score,
