       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-resume-screening','dsh-resume-screening','wangzhanchao883','https://github.com/wangzhanchao883/dsh-resume-screening',NULL,'tools','Resume screening plugin for HR in DeepSeek Harness: ingest up to 100k Word/PDF/Excel resumes into one searchable library with skills / coarse categories / ingest time, auto-ingest & de-dupe new resumes, then screen by plain-language criteria — rule pre-filter in the database plus LLM fine-judge on the shortlisted few, CSV export. Works on DeepSeek Harness 0.1.7 through 0.2.x, tested on 0.2.0-rc.1.','面向 HR 的简历筛选插件:把 Word/PDF/Excel 简历统一收进简历库建档(技能/粗分类/入库时间),新简历自动入库、重复自动去重;用大白话下指令即可筛选,硬性条件靠库内规则精准过滤,入围的少数人再由 LLM 精判适配度,结果可导出、可追溯。 支持 DSH 0.1.7 ~ 0.2.x,已在 0.2.0-rc.1 实测。','dsh-resume-screening',NULL,'dsh plugin --profile web add dsh-resume-screening','npm',0,1389,1389,'0.1.5','2026-09-11','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'d571161e')
