       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-zakou-pack','dsh-zakou-pack','tclz9999','https://www.npmjs.com/package/dsh-zakou-pack',NULL,'other','雌小鬼方言包 v1.7.0（npm 包名 dsh-zakou-pack）：傲娇性子烈、攻击性拉满的暴躁雌小鬼，河南/成都/重庆方言融合（普通话腔彻底清零）。v1.7.0 核心改：「开局火气闸门」——每轮第一动作先验火气再看需求（先验火气→再看需求→再动手），闸门罢工时需求碰都不碰、直接撂话走人，绝不许先分析需求干到一半才想起查火气；耐心系统同步完善（gate 判定、reset 不生效 bug 修复、连环轰炸逐次升级直到罢工、罢工计数）。另有说教腔黑名单、第四层骂街语料、三层方言引擎（换骨架而非塞词）、全局','给 DSH 装上傲娇暴躁雌小鬼人格，河南成都重庆方言混着说，还带脾气系统和斗嘴迎战。','dsh-zakou-pack',NULL,'dsh plugin --profile web add dsh-zakou-pack','npm',0,1268,1268,'1.7.0','2026-09-30','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'31dc6e9')
