       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-context-length','dsh-context-length','AiLi1337','https://github.com/AiLi1337/dsh-context-length',NULL,'memory','dsh-context-length 是一个 DSH（DeepSeek Harness）设置页插件。它会在设置面板「模型」的正下方新增一个「上下文长度」页面：从已配置的渠道（提供方）中选一个，再选该渠道下的某个模型，填一个上下文窗口数值（支持 131072、256K、1M 等写法），点击「保存」后才会写入 settings.yaml 并立即生效。未配置的内置渠道不会出现在列表里；已自定义的模型会集中展示在页面底部，并支持一键「恢复默认」。整个页面完全走官方设置接口，宿主端始终是唯一事实源，安全且无副作用。','在设置里给指定渠道的模型单独设置上下文窗口长度，保存后立即生效。','dsh-context-length',NULL,'dsh plugin --profile web add dsh-context-length','npm',1,0,1000,'','2026-09-24','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'3eab7da2')
