       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:2754lm/dsh-theme-newsprint','dsh-theme-newsprint','2754LM','https://github.com/2754LM/dsh-theme-newsprint',NULL,'theme','报纸衬线 · Newsprint Serif — DSH 主题插件：暖白报纸 + 纯黑中性灰 + 衬线正文 + 报纸排版笔画','把报纸排版的衬线质感搬进 DSH 界面，暖白纸配墨色字，纯 CSS 零配置换肤。',NULL,NULL,'dsh plugin --profile web add github:2754LM/dsh-theme-newsprint','github',1,0,1000,'','2026-09-16','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'a0ffaba5')
