       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-dev-git-graph','dsh-dev-git-graph#dsh-dev-git-graph','kp-z','https://github.com/kp-z/dsh-dev-git-graph/tree/main/packages/dsh-dev-git-graph',NULL,'dev','A Git Graph tab for DSH Web: a faithful port of vscode-git-graph 1.30.0 that registers a native tab in the dsh-better-sidebar right rail (prerequisite), auto-binds to the session workspace, runs the full git operations (checkout/merge/rebase/push/tag/stash) directly on the host, and opens file diffs in the built-in DiffTab.','DSH Web 的 vscode-git-graph 1.30.0 忠实移植：入驻 dsh-better-sidebar 右侧栏的原生 Git Graph 提交图 tab（前置依赖），自动绑定会话工作区，host 直跑全套 git 操作（checkout/merge/rebase/push/tag/stash），文件 diff 复用内置 DiffTab 打开。','dsh-dev-git-graph',NULL,'dsh plugin --profile web add dsh-dev-git-graph','npm',0,988,988,'0.1.3','2026-09-04','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'3be27241')
