       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-tauri-turnrewind','dsh-tauri-turnrewind','yingtianlan','https://github.com/yingtianlan/dsh-tauri-turnrewind',NULL,'dev','Turn-level workspace undo for Git worktrees: every agent turn gets a private snapshot, /undo previews a red/green diff card that is confirmed in place, files changed after the turn are refused with a conflict diff unless --force or --skip-conflicts is passed, and HEAD, index, stash and commit history of the user repository are never written.','Git worktree 的 turn 级工作区撤销：每个 turn 建私有快照，/undo 先出红绿 diff 预览卡、卡内确认；turn 之后被改过的文件拒绝用冲突 diff 覆盖，只有显式 --force 或 --skip-conflicts 才继续；不写用户仓库的 HEAD、index、stash 与提交历史。','dsh-tauri-turnrewind',NULL,'dsh plugin --profile web add dsh-tauri-turnrewind','npm',0,787,787,'0.3.1','2026-09-08','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'2d1acb0a')
