INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-plugin-content-policy','dsh-redaction#dsh-plugin-content-policy','L-ingqin12','https://github.com/L-ingqin12/dsh-redaction/tree/main/packages/dsh-plugin-content-policy',NULL,'security','Preventive content policy for tool results: rewrites matched text, and drops or truncates whole fields by path before a result is normalised, rendered or persisted, so an unreviewed payload never enters it. Ships inert with no built-in category or domain blocklist.','工具结果的预防式内容策略：改写命中文本，并按字段路径整段丢弃或截断，让未经审查的载荷在结果被规范化/渲染/落盘之前就进不去。随包为真空操作，不含任何内置的类别或域名黑名单。','dsh-plugin-content-policy',NULL,'dsh plugin --profile web add dsh-plugin-content-policy','npm',0,727,727,'0.2.1','2026-09-15','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'410228f6')
