INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-plugin-redact','dsh-redaction#dsh-plugin-redact','L-ingqin12','https://github.com/L-ingqin12/dsh-redaction/tree/main/packages/dsh-plugin-redact',NULL,'security','In-place redaction and row-level rollback for session logs, preserving the seq-equals-row-index invariant that makes deleting a middle row corrupt the entire log. Originals are copied to a quarantine sibling before any write, and the reader''s own semantics are replayed as a pre-write gate.','会话日志的原地脱敏与按行回退：守住「每行 seq 必须等于它的行号」这一不变式（删中间行会让整份日志打不开）。任何写入前先把原文复制成隔离备份，并以读取端自身的语义作为写前闸门。','dsh-plugin-redact',NULL,'dsh plugin --profile web add dsh-plugin-redact','npm',0,725,725,'0.1.1','2026-09-15','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'4f450baf')
     ON CONFLICT(id) DO UPDATE SET stars=excluded.stars, downloads=excluded.downloads, score=excluded.score,
