       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-session-keepwarm','dsh-session-keepwarm','dzwalker','https://github.com/dzwalker/dsh-session-keepwarm',NULL,'session','Keeps the most recently used sessions resident in the browser so switching back reuses the already loaded history instead of re-reading it; the number of resident sessions is configurable and the plugin can be switched off.','让浏览器最近用过的会话保持常驻：切走再切回来直接复用已加载的历史、不再重新读取；常驻数量可配置，并可整体关闭。','dsh-session-keepwarm',NULL,'dsh plugin --profile web add dsh-session-keepwarm','npm',0,384,384,'0.1.1','2026-10-11','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'809e821b')
