INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-compaction-policy','dsh-compaction-policy','zyd232','https://github.com/zyd232/dsh-compaction-policy',NULL,'session','Stops DeepSeek Harness from compacting (summarizing) your conversation far too early. Without it, compaction fires around half-full on smaller context windows; with it, compaction waits until the window is as full as you want (80% by default), settable per provider/model. It only changes when compaction happens — what a summary keeps is still DSH’s decision.','让 DeepSeek Harness 不再过早压缩对话（把早期内容总结掉）。默认行为下，上下文窗口不大的模型（十几万 token 那种）常常在半满出头就开始压缩；装上它之后，压缩会等你设定的比例（默认 80%）到了才发生，并且可以按 provider/model 分别设置。它只改“什么时候压缩”，一次压缩保留哪些内容仍由 DSH 决定。','dsh-compaction-policy',NULL,'dsh plugin --profile web add dsh-compaction-policy','npm',0,377,377,'0.1.1','2026-10-13','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'74d89329')
