       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-prompt-system','dsh-prompt-system','yuloong07-star','https://github.com/yuloong07-star/dsh-prompt-system',NULL,'tools','Prompt optimizer in the composer: rewrites the draft into an eleven-section analytical prompt using the conversation, workspace files and the session''s selected model, with one-click undo.','输入框内的提示词优化器：结合对话历史、工作区文件与会话选定模型，把草稿改写为十一节分析式提示词，支持一键撤销。','dsh-prompt-system',NULL,'dsh plugin --profile web add dsh-prompt-system','npm',0,377,377,'0.1.0','2026-10-01','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'b2c9453c')
