INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@nilesh32236/dsh-squad','dsh-squad','nilesh32236','https://github.com/nilesh32236/dsh-squad',NULL,'agent','Cross-workspace worker fleets: one orchestrating session spawns named worker sessions in other project workspaces, queues or steers tasks into them, watches them in the background via a real host job, and collects their reports. Worker completions deliver themselves to the orchestrator''s session rather than needing to be polled, so an idle orchestrator still reacts. Escalations and failed workers deliver by steer when the orchestrator is mid-turn and by queue when it is idle; a turn that ends without a report counts as a failure and the worker is replaced after a configurable limit. The roster persists to disk and each worker session carries a durable title, so a restart neither loses the fleet nor spawns duplicate sessions. Ships five agent presets at full plugin parity with the standard preset.','跨工作区的多智能体工舰队：一个编排会话在其他项目工作区中创建具名的 worker 会话，向其排队或插队下发任务，以后台任务的方式监视其进度，并收集其报告。worker 完成后主动把消息投递到编排会话，无需轮询，空闲的编排器同样能及时反应。当编排器正在执行任务时，升级提问与失败通知以 steer 方式送达，空闲时以 queue 方式送达；一个回合结束时若未提交报告即判定为失败，达到阈值后自动替换该 worker。名册持久化到磁盘，且每个 worker 会话带有持久标题，重启既不会丢失工舰队，也不会产生重复会话。附带五个智能体预设，插件清单与 standard 预设完全一致。','@nilesh32236/dsh-squad',NULL,'dsh plugin --profile web add @nilesh32236/dsh-squad','npm',0,343,343,'1.1.0','2026-10-13','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'53b263c0')
     ON CONFLICT(id) DO UPDATE SET stars=excluded.stars, downloads=excluded.downloads, score=excluded.score,
