       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:project-cross-migration','project-cross-migration','zhouxin121','https://github.com/zhouxin121/project-cross-migration',NULL,'docs','Registers the project-cross-migration skill for DSH: five-layer agent project migration (conversations, memory, persona, tools, environment) with entry validation, JSONL integrity checks and readable restore. 1,418-message real migration verified across three platforms; pure Python stdlib, MIT.','为 DSH 注册 project-cross-migration 技能：对话/记忆/人格/工具/环境五层迁移，含入口校验、JSONL 完整性检查与可读还原。三平台 1418 条消息真实迁移实测；纯 Python 标准库，MIT。','project-cross-migration',NULL,'dsh plugin --profile web add project-cross-migration','npm',0,334,334,'2.5.1','2026-10-13','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'7b045d65')
