INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-todo-guard','dsh-plugins#dsh-todo-guard','wxlei2004','https://github.com/wxlei2004/dsh-plugins/tree/main/packages/dsh-todo-guard',NULL,'agent','Task-list staleness guard for DeepSeek Harness: watches the session event stream and counts tool calls since the last todo_write; past a configurable threshold it appends one short notice before the next step, quoting the current list, so the model writes it back to the real progress instead of leaving a stale snapshot on screen. Pure prompt injection, no blocking and no data mutation.','任务清单陈旧度守卫：监听会话事件流，统计上一次 todo_write 之后又发生了多少次工具调用；超过可配置阈值时在下一步之前追加一条简短提醒，并附上当前清单内容，让模型把清单写回真实进度，而不是在界面上留一份过期的快照。纯提示注入，不阻断流程，也不改动任何数据。','dsh-todo-guard',NULL,'dsh plugin --profile web add dsh-todo-guard','npm',0,308,308,'0.1.0','2026-10-08','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'fad9ab8d')
