INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:mu915275-cmd/dsh-boot-animation','dsh-boot-animation','mu915275-cmd','https://github.com/mu915275-cmd/dsh-boot-animation',NULL,'ui','Plays an intro full-frame on a new conversation, or every time you open the one you pinned. Four clips ship inside the plugin itself, embedded in code with no separate video files, and an in-app library switches between them, previews the choice, and accepts your own clip. The picker has two independent sections, so the intro animation and the workspace wallpaper are picked separately; the wallpaper can be a still or a looping tail of the last N seconds, with independent transparency for the picture and the sidebar plus three blur levels. The sidebar and the workspace also get a text colour each, for when the picture is at full strength and the theme own text no longer reads.','打开新对话、或每次打开你钉住的那个会话时，铺满窗口播放一段片头动画。插件自带四段片头，直接内嵌在代码里（不带独立的视频文件）；界面里的片库可切换、可预览，也能随时换成你自己的片子。片库分成「入场动画」和「工作区壁纸」两个分区，两者各自独立选段；壁纸可以是静帧，或只循环片尾 N 秒的动态，画面与侧边栏各有独立透明度，另有三档模糊。工作区与侧边栏还各有一个字体颜色，画面全强度时主题自带的字看不清，就靠它。',NULL,NULL,'dsh plugin --profile web add github:mu915275-cmd/dsh-boot-animation','github',0,0,0,'','2026-10-11','2026-10-14T11:50:46.187Z','2026-10-14T11:50:46.187Z',0,NULL,'8d1858ce')
